/**
 * store-slice — composable zustand slices that mirror TanStack Query.
 *
 * Single entry point, so consumers can `import { createEntitySlice, useSyncQuery }
 * from '@/lib/store-slice'` instead of reaching into subfolders.
 */

export * from './types/query-state';
export * from './types/slice';

export * from './lib/query-snapshot';
export * from './lib/create-entity-slice';
export * from './lib/create-list-slice';
export * from './lib/create-entity-access';

export * from './hooks/use-sync-query';

/**
 * Query state types — derived from TanStack Query, never re-declared.
 *
 * Everything here is a `Pick` (or a rename) of the library's own
 * `UseQueryResult`, so the store's vocabulary cannot drift from TanStack's.
 * Two consequences worth knowing:
 *
 *  - A real `useQuery(...)` result is assignable to `QuerySnapshot` as-is.
 *    `syncQuery(useGetCrmById(id))` type-checks with no adapter.
 *  - Semantic changes in the library (v5 redefined `isLoading` and added
 *    `isPending`) surface as type errors instead of silently meaning
 *    something new.
 */

import type { UseQueryResult } from '@tanstack/react-query';

/**
 * The `UseQueryResult` fields the store mirrors.
 *
 * This union is the single source of truth: state keys, setter names, and the
 * runtime copy loop all derive from it. Add a field here (and to
 * `MIRRORED_QUERY_FIELDS` beside it) and every entity in the app grows the
 * matching state key and setter.
 */
export type MirroredQueryField =
  | 'data'
  | 'error'
  | 'isPending'
  | 'isLoading'
  | 'isFetching'
  | 'isError'
  | 'isSuccess';

/**
 * A point-in-time snapshot of a query, typed exactly as TanStack types it
 * (`data: TData | undefined`, `error: TError | null`, flags `boolean`).
 *
 * This is both the sync-input type and the stored-state type — there is no
 * separate "normalized" shape to remember.
 */
export type QuerySnapshot<TData, TError = Error> = Pick<
  UseQueryResult<TData, TError>,
  MirroredQueryField
>;

/**
 * The list flavour of `QuerySnapshot`.
 *
 * The keys are renamed rather than reused (`list` / `isListLoading` instead of
 * `data` / `isLoading`) for a specific reason: an entity slice and a list
 * slice for the SAME entity both live on the flat store, so a collection's
 * loading state and the main entity's loading state have to be two
 * independently observable facts.
 */
export type ListQuerySnapshot<TItem, TError = Error> = {
  list: TItem[] | undefined;
  listError: TError | null;
  isListPending: boolean;
  isListLoading: boolean;
  isListFetching: boolean;
  isListError: boolean;
  isListSuccess: boolean;
};

/** Identifier type accepted by the list slice's by-id operations. */
export type EntityId = string | number;

/**
 * Slice types — the shape of a generated entity/list slice.
 *
 * Nothing in here is written per entity. Given a name and a data type, these
 * types compute the flat state keys, the setter names, and their signatures.
 * The only thing an author declares by hand is the signatures of their own
 * getters and actions.
 */

import type {
  EntityId,
  ListQuerySnapshot,
  MirroredQueryField,
  QuerySnapshot,
} from './query-state';

// ─────────────────────────────────────────────────────────────────────────────
// Generic helpers
// ─────────────────────────────────────────────────────────────────────────────

/** Flattens an intersection so editor tooltips show the resolved object. */
export type Prettify<T> = {
  [K in keyof T]: T[K];
  // eslint-disable-next-line @typescript-eslint/no-empty-object-type
} & {};

/** `{ data: T }` + `'crm_'` → `{ crm_data: T }` */
export type PrefixedKeys<T, P extends string> = {
  [K in keyof T as `${P}${string & K}`]: T[K];
};

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type AnyFn = (...args: any[]) => unknown;

/**
 * "Every member of T is a function", as a mapped type over `keyof T` rather
 * than `Record<string, AnyFn>`.
 *
 * This distinction is load-bearing: an `interface` has no implicit index
 * signature, so `interface CrmGetters {...}` is NOT assignable to
 * `Record<string, AnyFn>` while an identical `type` alias is. Used as a
 * self-referential constraint (`TGetters extends FnsOf<TGetters>`) it accepts
 * both, while still rejecting non-function members.
 */
export type FnsOf<T> = { [K in keyof T]: AnyFn };

/** Empty-object default for optional getters/actions generics. */
export type None = Record<never, never>;

/** Minimal structural `set` — compatible with zustand's `StateCreator` set. */
export type SetLike<TStore> = (
  partial: Partial<TStore> | ((state: TStore) => Partial<TStore>)
) => void;

/** Adds `Record<Key, T>` to an intersection only when `T` has members. */
export type WhenNonEmpty<Key extends string, T> = [keyof T] extends [never]
  ? unknown
  : Record<Key, T>;

// ─────────────────────────────────────────────────────────────────────────────
// Entity slice
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Flat, prefixed, OPTIONAL query-state keys: `crm_data`, `crm_isLoading`, …
 *
 * Optional is deliberate. It means a slice implementation needs no
 * initial-state block at all, and — more importantly — it models reality:
 * `crm_isLoading: false` would assert "this query is not loading", which is
 * untrue before the query has ever been observed. `undefined` says exactly
 * that, and stays distinguishable from a real `false`.
 */
export type EntityState<TName extends string, TData, TError = Error> = Partial<
  PrefixedKeys<QuerySnapshot<TData, TError>, `${TName}_`>
>;

/**
 * One `set{Field}` per mirrored query field, mapped from `QuerySnapshot` so
 * the names and value types can never disagree with the state keys.
 */
export type FieldSetters<TData, TError = Error> = {
  [K in MirroredQueryField as `set${Capitalize<K>}`]: (
    value: QuerySnapshot<TData, TError>[K]
  ) => void;
};

export type EntitySetters<TData, TError = Error> = FieldSetters<
  TData,
  TError
> & {
  /**
   * Mirrors a whole `useQuery` result into the store in one `set` call.
   *
   * This is the piece that makes mirroring *all* query state cheaper than
   * mirroring just `data` — which is what stops `isLoading` and `error` from
   * being declared in a slice and then written by nothing.
   */
  syncQuery: (query: QuerySnapshot<TData, TError>) => void;
  /** Shallow-merges a patch into current data. No-op while data is unset. */
  patchData: (patch: Partial<TData>) => void;
  /** Clears every mirrored field back to `undefined`. */
  reset: () => void;
};

export type EntitySlice<
  TName extends string,
  TData,
  TError = Error,
  TGetters extends object = None,
  TActions extends object = None,
> = EntityState<TName, TData, TError> &
  Record<`${TName}Setters`, EntitySetters<TData, TError>> &
  WhenNonEmpty<`${TName}Getters`, TGetters> &
  WhenNonEmpty<`${TName}Actions`, TActions>;

/**
 * Declaration-first alias for composing a store type.
 *
 * ```ts
 * type AppStore =
 *   DefineEntitySlice<'crm', CrmMeta, { getters: CrmGetters }> &
 *   DefineEntitySlice<'survey', SurveyMeta>;
 * ```
 */
export type DefineEntitySlice<
  TName extends string,
  TData,
  TConfig extends {
    error?: unknown;
    getters?: object;
    actions?: object;
  } = None,
> = Prettify<
  EntitySlice<
    TName,
    TData,
    TConfig extends { error: infer E } ? E : Error,
    TConfig extends { getters: infer G extends object } ? G : None,
    TConfig extends { actions: infer A extends object } ? A : None
  >
>;

export interface CreateEntitySliceOptions<
  TStore,
  TData,
  TError,
  TGetters extends object,
  TActions extends object,
> {
  /**
   * Derived reads. `get` returns the WHOLE store, which is the reason getters
   * live on the slice rather than being free-standing selectors.
   */
  getters?: (get: () => TStore) => TGetters;
  /** Custom logic — anything beyond a plain field write. */
  actions?: (set: SetLike<TStore>, get: () => TStore) => TActions;
  /**
   * Override any subset of the generated setters.
   *
   * `defaults` is handed in so an override can decorate rather than
   * reimplement — without it, every override would have to re-do the
   * key-writing it is trying to extend, reintroducing the boilerplate in the
   * highest-risk place.
   */
  setters?: (
    set: SetLike<TStore>,
    get: () => TStore,
    defaults: EntitySetters<TData, TError>
  ) => Partial<EntitySetters<TData, TError>>;
}

// ─────────────────────────────────────────────────────────────────────────────
// List slice
// ─────────────────────────────────────────────────────────────────────────────

export type ListField =
  | 'list'
  | 'listError'
  | 'isListPending'
  | 'isListLoading'
  | 'isListFetching'
  | 'isListError'
  | 'isListSuccess';

/** List query keys plus the current selection, all optional and prefixed. */
export type ListState<
  TName extends string,
  TItem,
  TId extends EntityId = EntityId,
  TError = Error,
> = Partial<
  PrefixedKeys<ListQuerySnapshot<TItem, TError>, `${TName}_`> &
    Record<`${TName}_selectedId`, TId>
>;

export type ListFieldSetters<TItem, TError = Error> = {
  [K in ListField as `set${Capitalize<K>}`]: (
    value: ListQuerySnapshot<TItem, TError>[K]
  ) => void;
};

export type ListSetters<
  TItem,
  TId extends EntityId = EntityId,
  TError = Error,
> = ListFieldSetters<TItem, TError> & {
  /** Mirrors a raw list-returning `useQuery` result in one `set` call. */
  syncListQuery: (query: QuerySnapshot<TItem[], TError>) => void;
  /** Clears every list field, and the selection, back to `undefined`. */
  resetList: () => void;
  /** Marks an entity as selected without disturbing the main `_data` entity. */
  setSelectedId: (id: TId | undefined) => void;
  /** Shallow-merges a patch into the list member with the given id. */
  updateById: (id: TId, patch: Partial<TItem>) => void;
  /** Replaces the member with a matching id, or appends when absent. */
  upsertById: (item: TItem) => void;
  removeById: (id: TId) => void;
};

export type ListGetters<TItem, TId extends EntityId = EntityId> = {
  getById: (id: TId) => TItem | undefined;
  /**
   * The entity addressed by `_selectedId`, resolved against the list on read.
   * Storing a pointer rather than a second copy is what keeps the selection
   * from drifting out of sync with list contents.
   */
  getSelected: () => TItem | undefined;
};

export type ListSlice<
  TName extends string,
  TItem,
  TId extends EntityId = EntityId,
  TError = Error,
> = ListState<TName, TItem, TId, TError> &
  Record<`${TName}ListSetters`, ListSetters<TItem, TId, TError>> &
  Record<`${TName}ListGetters`, ListGetters<TItem, TId>>;

export interface CreateListSliceOptions<
  TStore,
  TItem,
  TId extends EntityId,
  TError,
> {
  /** How to read an item's id. Defaults to `item.id`. */
  selectId?: (item: TItem) => TId;
  /** Override any subset of the generated list setters. */
  setters?: (
    set: SetLike<TStore>,
    get: () => TStore,
    defaults: ListSetters<TItem, TId, TError>
  ) => Partial<ListSetters<TItem, TId, TError>>;
}

/**
 * Runtime counterparts of the query-state types.
 *
 * The `as const satisfies` pairing on each field list is what keeps the
 * runtime arrays and their type unions from drifting apart — remove a field
 * from one and the other fails to compile.
 */

import type {
  ListField,
  PrefixedKeys,
} from '../types/slice';
import type {
  ListQuerySnapshot,
  MirroredQueryField,
  QuerySnapshot,
} from '../types/query-state';

/** Every `UseQueryResult` field mirrored into the store. */
export const MIRRORED_QUERY_FIELDS = [
  'data',
  'error',
  'isPending',
  'isLoading',
  'isFetching',
  'isError',
  'isSuccess',
] as const satisfies readonly MirroredQueryField[];

/** Every list-flavoured field mirrored into the store. */
export const LIST_FIELDS = [
  'list',
  'listError',
  'isListPending',
  'isListLoading',
  'isListFetching',
  'isListError',
  'isListSuccess',
] as const satisfies readonly ListField[];

/**
 * Copies only the mirrored fields out of a raw `useQuery` result, so the store
 * never accidentally captures `refetch` and friends.
 */
export const pickQuerySnapshot = <TData, TError = Error>(
  query: QuerySnapshot<TData, TError>
): QuerySnapshot<TData, TError> => {
  const out: Record<string, unknown> = {};
  for (const field of MIRRORED_QUERY_FIELDS) out[field] = query[field];
  return out as QuerySnapshot<TData, TError>;
};

/** Renames a query snapshot's keys into their list-flavoured counterparts. */
export const pickListQuerySnapshot = <TItem, TError = Error>(
  query: QuerySnapshot<TItem[], TError>
): ListQuerySnapshot<TItem, TError> => ({
  list: query.data,
  listError: query.error,
  isListPending: query.isPending,
  isListLoading: query.isLoading,
  isListFetching: query.isFetching,
  isListError: query.isError,
  isListSuccess: query.isSuccess,
});

/** Runtime counterpart of `PrefixedKeys` — prefixes every key of an object. */
export const prefixKeys = <T extends Record<string, unknown>, P extends string>(
  prefix: P,
  obj: T
): PrefixedKeys<T, `${P}_`> => {
  const out: Record<string, unknown> = {};
  for (const key of Object.keys(obj)) out[`${prefix}_${key}`] = obj[key];
  return out as PrefixedKeys<T, `${P}_`>;
};

/** Shared by both factories when building `set{Field}` names. */
export const capitalize = <T extends string>(value: T) =>
  (value.charAt(0).toUpperCase() + value.slice(1)) as Capitalize<T>;

/**
 * `createEntitySlice` — generates a whole single-entity zustand slice from a
 * name and a data type.
 *
 * ```ts
 * const createCrmSlice = createEntitySlice<CrmMeta>()<'crm', AppStore>('crm');
 * ```
 *
 * produces `crm_data`, `crm_error`, `crm_isPending`, `crm_isLoading`,
 * `crm_isFetching`, `crm_isError`, `crm_isSuccess` and a `crmSetters` object
 * with a setter per field plus `syncQuery` / `patchData` / `reset`.
 *
 * Three namespaces, each with one job:
 *   `{name}Setters` — generated field writers. Never contains logic you wrote.
 *   `{name}Getters` — your derived reads. Receive `get`, should not write.
 *   `{name}Actions` — your custom logic. Receive `set` and `get`.
 *
 * Splitting them means "is there business logic hiding in here?" is answerable
 * by location rather than by reading every function body.
 */

import type {
  CreateEntitySliceOptions,
  EntitySetters,
  EntitySlice,
  FieldSetters,
  FnsOf,
  None,
  SetLike,
} from '../types/slice';
import {
  capitalize,
  MIRRORED_QUERY_FIELDS,
  pickQuerySnapshot,
  prefixKeys,
} from './query-snapshot';

/**
 * Curried so `TData` (and optionally `TError`) is given explicitly while the
 * name, store and getter/action shapes infer.
 *
 * The returned function is a plain zustand slice creator — `(set, get) => …` —
 * so it spreads straight into `create<AppStore>()((set, get) => ({ ... }))`.
 *
 * Note on `TStore`: a slice whose getters read the whole store needs
 * `AppStore` to type `get`, so `AppStore` must be declared before the creator
 * rather than inferred from it. See the README's "circularity rule".
 */
export const createEntitySlice =
  <TData, TError = Error>() =>
  <
    TName extends string,
    TStore = unknown,
    TGetters extends FnsOf<TGetters> = None,
    TActions extends FnsOf<TActions> = None,
  >(
    name: TName,
    options?: CreateEntitySliceOptions<
      TStore,
      TData,
      TError,
      TGetters,
      TActions
    >
  ) =>
  (
    set: SetLike<TStore>,
    get: () => TStore
  ): EntitySlice<TName, TData, TError, TGetters, TActions> => {
    const key = (field: string) => `${name}_${field}`;
    const write = (partial: Record<string, unknown>) =>
      set(partial as Partial<TStore>);

    const fieldSetters = Object.fromEntries(
      MIRRORED_QUERY_FIELDS.map((field) => [
        `set${capitalize(field)}`,
        (value: unknown) => write({ [key(field)]: value }),
      ])
    ) as FieldSetters<TData, TError>;

    const defaults: EntitySetters<TData, TError> = {
      ...fieldSetters,
      syncQuery: (query) =>
        write(
          prefixKeys(
            name,
            pickQuerySnapshot(query) as unknown as Record<string, unknown>
          )
        ),
      patchData: (patch) => {
        const current = (get() as Record<string, unknown>)[key('data')] as
          | TData
          | undefined;
        // Safe to call before the query resolves — that is what makes this
        // usable for optimistic updates without a guard at the call site.
        if (current == null) return;
        write({ [key('data')]: { ...current, ...patch } });
      },
      reset: () =>
        write(
          Object.fromEntries(
            MIRRORED_QUERY_FIELDS.map((field) => [key(field), undefined])
          )
        ),
    };

    const setters: EntitySetters<TData, TError> = {
      ...defaults,
      ...options?.setters?.(set, get, defaults),
    };

    return {
      [`${name}Setters`]: setters,
      ...(options?.getters ? { [`${name}Getters`]: options.getters(get) } : {}),
      ...(options?.actions
        ? { [`${name}Actions`]: options.actions(set, get) }
        : {}),
    } as EntitySlice<TName, TData, TError, TGetters, TActions>;
  };

/**
 * `createListSlice` — a collection of entities, mirrored from a list-returning
 * query, plus by-id operations and selection.
 *
 * Composes with `createEntitySlice` under the SAME name. The entity slice owns
 * "the one main entity" (`crm_data`); the list slice owns the collection
 * (`crm_list`) and lets you address any member by id without disturbing the
 * main entity. They share a prefix but no key names, so both sit on the flat
 * store together.
 *
 * Opt in per entity: an entity that never needs a collection simply does not
 * compose one, so there is no empty `crm_list` to misread as "loaded, empty".
 */

import type { EntityId } from '../types/query-state';
import type {
  CreateListSliceOptions,
  ListFieldSetters,
  ListGetters,
  ListSetters,
  ListSlice,
  SetLike,
} from '../types/slice';
import { capitalize, LIST_FIELDS, pickListQuerySnapshot } from './query-snapshot';

export const createListSlice =
  <TItem, TId extends EntityId = EntityId, TError = Error>() =>
  <TName extends string, TStore = unknown>(
    name: TName,
    options?: CreateListSliceOptions<TStore, TItem, TId, TError>
  ) =>
  (
    set: SetLike<TStore>,
    get: () => TStore
  ): ListSlice<TName, TItem, TId, TError> => {
    const key = (field: string) => `${name}_${field}`;
    const write = (partial: Record<string, unknown>) =>
      set(partial as Partial<TStore>);
    const selectId =
      options?.selectId ?? ((item: TItem) => (item as { id: TId }).id);

    const readList = () =>
      ((get() as Record<string, unknown>)[key('list')] as TItem[] | undefined) ??
      [];

    const fieldSetters = Object.fromEntries(
      LIST_FIELDS.map((field) => [
        `set${capitalize(field)}`,
        (value: unknown) => write({ [key(field)]: value }),
      ])
    ) as ListFieldSetters<TItem, TError>;

    const defaults: ListSetters<TItem, TId, TError> = {
      ...fieldSetters,
      syncListQuery: (query) => {
        const snapshot = pickListQuerySnapshot(query);
        write(
          Object.fromEntries(
            Object.entries(snapshot).map(([field, value]) => [key(field), value])
          )
        );
      },
      resetList: () =>
        write(
          Object.fromEntries(
            [...LIST_FIELDS, 'selectedId'].map((field) => [
              key(field),
              undefined,
            ])
          )
        ),
      setSelectedId: (id) => write({ [key('selectedId')]: id }),
      updateById: (id, patch) =>
        write({
          [key('list')]: readList().map((item) =>
            selectId(item) === id ? { ...item, ...patch } : item
          ),
        }),
      upsertById: (item) => {
        const list = readList();
        const id = selectId(item);
        const exists = list.some((member) => selectId(member) === id);
        write({
          [key('list')]: exists
            ? list.map((member) => (selectId(member) === id ? item : member))
            : [...list, item],
        });
      },
      removeById: (id) =>
        write({
          [key('list')]: readList().filter((item) => selectId(item) !== id),
        }),
    };

    const setters: ListSetters<TItem, TId, TError> = {
      ...defaults,
      ...options?.setters?.(set, get, defaults),
    };

    const getters: ListGetters<TItem, TId> = {
      getById: (id) => readList().find((item) => selectId(item) === id),
      getSelected: () => {
        const selectedId = (get() as Record<string, unknown>)[
          key('selectedId')
        ] as TId | undefined;
        if (selectedId === undefined) return undefined;
        return readList().find((item) => selectId(item) === selectedId);
      },
    };

    return {
      [`${name}ListSetters`]: setters,
      [`${name}ListGetters`]: getters,
    } as ListSlice<TName, TItem, TId, TError>;
  };

/**
 * `createEntityAccess` — optional sugar over raw selectors.
 *
 * Raw selectors already work (`useAppStore(s => s.crm_data)`), but every call
 * site repeats the prefix. This binds a store hook to one slice name once:
 *
 * ```ts
 * export const crm = createEntityAccess<CrmMeta>()(useAppStore, 'crm');
 *
 * crm.useData()      // CrmMeta | undefined
 * crm.useIsLoading() // boolean — the undefined "never observed" case coalesced
 * crm.useSetters()   // EntitySetters<CrmMeta>
 * crm.get()          // outside React
 * ```
 *
 * This generalizes the common "one hand-written typed hook per entity"
 * pattern into a single factory.
 */

import type { EntitySetters } from '../types/slice';
import type { MirroredQueryField } from '../types/query-state';

/** Structural shape of a zustand hook (`UseBoundStore<StoreApi<T>>`). */
export interface StoreHookLike<TStore> {
  <TReturn>(selector: (state: TStore) => TReturn): TReturn;
  getState: () => TStore;
}

/** The status half of a mirrored query, without `data`. */
export interface EntityStatus<TError = Error> {
  error: TError | null | undefined;
  isPending: boolean | undefined;
  isLoading: boolean | undefined;
  isFetching: boolean | undefined;
  isError: boolean | undefined;
  isSuccess: boolean | undefined;
}

export const createEntityAccess =
  <TData, TError = Error>() =>
  <TStore, TName extends string>(
    useStore: StoreHookLike<TStore>,
    name: TName
  ) => {
    const key = (field: MirroredQueryField) => `${name}_${field}`;
    const read = <T>(state: TStore, field: string) =>
      (state as Record<string, unknown>)[field] as T;
    const setters = (state: TStore) =>
      read<EntitySetters<TData, TError>>(state, `${name}Setters`);

    return {
      /** The mirrored entity, or `undefined` before the first sync. */
      useData: () => useStore((s) => read<TData | undefined>(s, key('data'))),
      /**
       * All status flags in one subscription. Builds a fresh object each
       * render — pair with zustand's `useShallow` if that shows up in a
       * profile.
       */
      useStatus: (): EntityStatus<TError> =>
        useStore((s) => ({
          error: read<TError | null | undefined>(s, key('error')),
          isPending: read<boolean | undefined>(s, key('isPending')),
          isLoading: read<boolean | undefined>(s, key('isLoading')),
          isFetching: read<boolean | undefined>(s, key('isFetching')),
          isError: read<boolean | undefined>(s, key('isError')),
          isSuccess: read<boolean | undefined>(s, key('isSuccess')),
        })),
      useIsLoading: () =>
        useStore(
          (s) => read<boolean | undefined>(s, key('isLoading')) ?? false
        ),
      useError: () =>
        useStore(
          (s) => read<TError | null | undefined>(s, key('error')) ?? null
        ),
      /** Stable across renders — safe to use in effect dependency arrays. */
      useSetters: () => useStore(setters),
      /** Just the sync callback, for `useSyncQuery`. */
      useSyncCallback: () => useStore((s) => setters(s).syncQuery),

      // Escape hatches for event handlers, tests, and non-React callers.
      get: () => read<TData | undefined>(useStore.getState(), key('data')),
      set: (data: TData | undefined) =>
        setters(useStore.getState()).setData(data),
      setters: () => setters(useStore.getState()),
    };
  };

'use client';

/**
 * The React glue. Replaces the hand-written mirroring effect:
 *
 * ```ts
 * // before — mirrors data only; loading and error never reach the store
 * const { setCrmData } = useAppStore(s => s.crmActions);
 * const { data } = useGetCrmById(id);
 * useEffect(() => { setCrmData(data ?? null); }, [data, setCrmData]);
 *
 * // after — every mirrored field, one line
 * useSyncQuery(useGetCrmById(id), useAppStore(s => s.crmSetters.syncQuery));
 * ```
 */

import { useEffect } from 'react';
import type { QuerySnapshot } from '../types/query-state';

/**
 * Mirrors a TanStack query into a store slice.
 *
 * Works for both entity (`syncQuery`) and list (`syncListQuery`) setters — the
 * hook only requires that the callback accepts the snapshot.
 */
export const useSyncQuery = <TData, TError = Error>(
  query: QuerySnapshot<TData, TError>,
  sync: (query: QuerySnapshot<TData, TError>) => void
): void => {
  useEffect(() => {
    sync(query);
    // Depends on the individual fields, not the result object: TanStack
    // returns a new object every render, so `[query]` would fire the effect
    // every render. The fields themselves are referentially stable, and
    // `sync` is stable because the setters object is created once with the
    // slice.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    sync,
    query.data,
    query.error,
    query.isPending,
    query.isLoading,
    query.isFetching,
    query.isError,
    query.isSuccess,
  ]);
};

/**
 * Syncs, and clears the slice on unmount so a layout leaves no stale entity
 * behind when the user navigates away.
 *
 * Opt-in rather than the default, because "keep showing the last entity while
 * the next one loads" is sometimes the behaviour you want.
 */
export const useSyncQueryWithCleanup = <TData, TError = Error>(
  query: QuerySnapshot<TData, TError>,
  sync: (query: QuerySnapshot<TData, TError>) => void,
  reset: () => void
): void => {
  useSyncQuery(query, sync);
  useEffect(() => reset, [reset]);
};
